script:
(function () {
  'use strict';
  // Ranks up to four rebate / discount / financing offers on the same vehicle by total cost.
  //   Taxable price = price - trade-in credit - cash off (a dealer price cut always lowers the taxed
  //     price; a manufacturer rebate only when the "rebate reduces the taxable price" box is ticked), >= 0.
  //   Loan = price - cash off - down - trade-in + owed (+ sales tax and fees when financed), >= 0.
  //   Payment M = L x i / (1 - (1 + i)^-n), i = APR / 12 (M = L / n at 0%).
  //   Total cost = price - cash off + sales tax + fees + total interest (the same basis for every offer).
  //   Cost in today's dollars = cash due at signing + M x (1 - (1 + s)^-n) / s, s = savings rate / 12,
  //     so offers with different terms can be compared on a present-value basis.
  // Verified in Node (scratchpad tests/autogroup/ar.test.js): $25,000 at 6% for 60 months = $483.32/mo
  //   (published closed-form value); the $50,000 / $1,000 rebate at 5% vs 2% (60 months, $10,000 down,
  //   7% tax, $2,000 fees paid upfront) case gives $735.98 and $701.11 a month and totals of $59,658.69
  //   and $57,566.62, the same as the live cash back or low interest calculator; at a 0% savings rate the
  //   present cost equals cash at signing + total of payments; blank, zero and negative inputs show an
  //   error with no NaN or Infinity on the page.
  var money = new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', maximumFractionDigits: 2 });
  var N = 4;

  function el(id) { return document.getElementById(id); }
  function setText(id, t) { el(id).textContent = t; }

  function read(id, blankAsZero) {
    var raw = String(el(id).value).trim();
    if (raw === '') return blankAsZero ? 0 : NaN;
    var v = Number(raw);
    return isFinite(v) ? v : NaN;
  }

  function monthlyPayment(principal, annualRate, months) {
    if (months <= 0 || principal <= 0) return 0;
    var i = annualRate / 12;
    if (i === 0) return principal / months;
    return principal * i / (1 - Math.pow(1 + i, -months));
  }

  function annuityFactor(monthlyRate, months) {
    if (monthlyRate === 0) return months;
    return (1 - Math.pow(1 + monthlyRate, -months)) / monthlyRate;
  }

  // b: shared deal inputs; o: one offer {cash, isCut, apr, months}
  function evaluate(b, o) {
    var lowersTax = o.isCut || b.rebateTax;
    var taxable = Math.max(0, b.price - (b.tradeCredit ? b.trade : 0) - (lowersTax ? o.cash : 0));
    var tax = taxable * b.taxRate / 100;
    var loan = Math.max(0, b.price - o.cash - b.down - b.trade + b.owed + (b.finance ? tax + b.fees : 0));
    var pmt = monthlyPayment(loan, o.apr / 100, o.months);
    var paid = pmt * o.months;
    var interest = Math.max(0, paid - loan);
    var upfront = b.down + (b.finance ? 0 : tax + b.fees);
    var present = upfront + pmt * annuityFactor(b.savings / 1200, o.months);
    return { loan: loan, tax: tax, pmt: pmt, paid: paid, interest: interest, upfront: upfront,
             total: b.price - o.cash + tax + b.fees + interest, present: present };
  }

  function rateText(v) { return String(Number(v.toFixed(3))) + '%'; }

  function clearResults() {
    setText('arVerdictTitle', '–'); setText('arVerdict', '');
    ['arBest', 'arSpread', 'arLowPay', 'arBestPresent'].forEach(function (id) { setText(id, '–'); });
    el('arTable').innerHTML = '';
  }

  function cell(tr, tag, text) {
    var c = document.createElement(tag);
    if (tag === 'th') c.setAttribute('scope', 'row');
    c.textContent = text;
    tr.appendChild(c);
  }

  function update() {
    var b = {
      price: read('arPrice'), down: read('arDown', true), trade: read('arTrade', true), owed: read('arOwed', true),
      taxRate: read('arTaxRate', true), fees: read('arFees', true), savings: read('arSavings', true),
      finance: el('arFinanceCosts').checked, tradeCredit: el('arTradeCredit').checked, rebateTax: el('arRebateTax').checked
    };
    var error = el('arError'), msg = '';
    if (isNaN(b.price) || b.price <= 0) msg = 'Enter a vehicle price greater than $0.';
    else if ([b.down, b.trade, b.owed, b.taxRate, b.fees, b.savings].some(function (v) { return isNaN(v) || v < 0; })) msg = 'Amounts and rates cannot be negative.';
    else if (b.taxRate > 20) msg = 'Enter a sales tax rate of 20% or less.';
    else if (b.savings > 20) msg = 'Enter a savings rate of 20% or less.';

    var offers = [];
    for (var k = 1; k <= N && !msg; k++) {
      if (!el('arUse' + k).checked) continue;
      var name = String(el('arName' + k).value).trim() || ('Offer ' + k);
      var o = { k: k, name: name, cash: read('arCash' + k, true), isCut: el('arType' + k).value === 'cut',
                apr: read('arApr' + k), months: read('arTerm' + k) };
      if (isNaN(o.cash) || o.cash < 0 || o.cash >= b.price) msg = name + ': enter cash off from $0 up to less than the vehicle price.';
      else if (isNaN(o.apr) || o.apr < 0 || o.apr > 40) msg = name + ': enter an interest rate from 0% to 40%.';
      else if (isNaN(o.months) || o.months < 1 || o.months > 96 || o.months % 1 !== 0) msg = name + ': enter a term of 1 to 96 whole months.';
      else offers.push(o);
    }
    if (!msg && offers.length < 2) msg = 'Tick at least two offers to compare.';
    if (!msg) {
      offers.forEach(function (o) { o.r = evaluate(b, o); });
      if (offers.every(function (o) { return o.r.loan <= 0.005; })) msg = 'Your down payment and trade-in cover the full cost, so there is no loan to compare.';
    }
    error.hidden = !msg;
    error.textContent = msg;
    if (msg) { clearResults(); return; }

    offers.sort(function (x, y) { return x.r.total - y.r.total || x.r.present - y.r.present || x.k - y.k; });
    var best = offers[0], worst = offers[offers.length - 1], second = offers[1];
    var lowPay = offers.slice().sort(function (x, y) { return x.r.pmt - y.r.pmt; })[0];
    var bestPv = offers.slice().sort(function (x, y) { return x.r.present - y.r.present; })[0];

    var gap = second.r.total - best.r.total;
    if (gap < 0.005) {
      setText('arVerdictTitle', 'A tie at the top: ' + best.name + ' and ' + second.name);
      setText('arVerdict', 'Both cost the same in total. Choose on monthly payment or loan length.');
    } else {
      setText('arVerdictTitle', 'Cheapest overall: ' + best.name);
      setText('arVerdict', best.name + ' costs ' + money.format(gap) + ' less than the next best offer (' + second.name +
        ') and ' + money.format(worst.r.total - best.r.total) + ' less than the most expensive (' + worst.name + ').' +
        (bestPv !== best ? ' Measured in today’s dollars at your savings rate, ' + bestPv.name + ' comes out ahead, because its payments are spread over a longer term or start smaller.' : ''));
    }
    setText('arBest', money.format(best.r.total));
    setText('arSpread', money.format(worst.r.total - best.r.total));
    setText('arLowPay', money.format(lowPay.r.pmt) + ' (' + lowPay.name + ')');
    setText('arBestPresent', bestPv.name);

    var body = el('arTable');
    body.innerHTML = '';
    offers.forEach(function (o, idx) {
      var tr = document.createElement('tr');
      cell(tr, 'td', String(idx + 1));
      cell(tr, 'th', o.name);
      cell(tr, 'td', money.format(o.cash));
      cell(tr, 'td', rateText(o.apr) + ' / ' + o.months + ' mo');
      cell(tr, 'td', money.format(o.r.loan));
      cell(tr, 'td', money.format(o.r.pmt));
      cell(tr, 'td', money.format(o.r.interest));
      cell(tr, 'td', money.format(o.r.tax));
      cell(tr, 'td', money.format(o.r.total));
      cell(tr, 'td', money.format(o.r.present));
      cell(tr, 'td', idx === 0 ? 'Cheapest' : '+' + money.format(o.r.total - best.r.total));
      body.appendChild(tr);
    });
  }

  document.addEventListener('DOMContentLoaded', function () {
    var form = el('arForm');
    if (!form) return;
    form.addEventListener('input', update);
    form.addEventListener('change', update);
    form.addEventListener('submit', function (e) { e.preventDefault(); });
    update();
  });
})();
